begin;
create table if not exists ai_provider_configs (id bigserial primary key,provider_code text not null unique check(provider_code in('openai','google','anthropic','custom')),display_name text not null,enabled boolean not null default false,api_key_ciphertext text,api_key_iv text,api_key_auth_tag text,base_url text,organization_id text,project_id text,default_text_model text,default_vision_model text,default_image_model text,capabilities jsonb not null default '[]'::jsonb,extra_config jsonb not null default '{}'::jsonb,last_test_status text not null default 'not_tested',last_test_message text,last_tested_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ai_task_routing(task_type text primary key,provider_code text not null check(provider_code in('openai','google','anthropic','custom')),model text,enabled boolean not null default false,quality text,size text,max_images_per_request integer not null default 1,max_retries integer not null default 0,fallback_provider_code text,fallback_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists ai_cost_safety_settings(id integer primary key default 1 check(id=1),monthly_budget_krw integer,daily_budget_krw integer,max_cost_per_product_krw integer,max_main_image_versions integer not null default 1,max_detail_images integer not null default 10,automatic_retry_enabled boolean not null default false,require_human_approval boolean not null default true,updated_at timestamptz not null default now());
insert into ai_cost_safety_settings(id) values(1) on conflict(id) do nothing;
commit;
